from PIL import Image
import sys
f=sys.argv[1]; cw=int(sys.argv[2]); ch=int(sys.argv[3])
im=Image.open(f).convert("RGB")
w,h=im.size
def cls(p):
    r,g,b=p
    mx=max(r,g,b); mn=min(r,g,b)
    if mx<70: return "#"
    if mx-mn<28:
        return " " if mx>225 else ("." if mx>170 else (":" if mx>110 else "+"))
    if r>=g and r>=b:
        if g>150 and b>150 and r>230: return "p"
        return "R"
    if g>=r and g>=b: return "G"
    return "B"
out=[]
for y in range(ch):
    row=""
    for x in range(cw):
        x0=x*w//cw; x1=max(x0+1,(x+1)*w//cw); y0=y*h//ch; y1=max(y0+1,(y+1)*h//ch)
        cnt={}
        for yy in range(y0,y1,2):
            for xx in range(x0,x1,2):
                c=cls(im.getpixel((xx,yy)))
                cnt[c]=cnt.get(c,0)+1
        row+=max(cnt.items(),key=lambda kv:kv[1])[0]
    out.append(row)
print(f, w, h)
print("\n".join(out))
