/* \uXXXX → 码点；非法十六进制返回 0xFFFFFFFF */

static unsigned int sb_json_hex4(const char *s)
{
  unsigned int v = 0;
  int i;

  for (i = 0; i < 4; i++)
    {
      char c = s[i];

      if (c >= '0' && c <= '9')
        {
          v = (v << 4) | (unsigned int)(c - '0');
        }
      else if (c >= 'a' && c <= 'f')
        {
          v = (v << 4) | (unsigned int)(c - 'a' + 10);
        }
      else if (c >= 'A' && c <= 'F')
        {
          v = (v << 4) | (unsigned int)(c - 'A' + 10);
        }
      else
        {
          return 0xFFFFFFFFu;
        }
    }

  return v;
}

/* 码点 → UTF-8，追加到 out[n]（out_size 含结尾 '\0' 预留），返回新长度 */

static size_t sb_json_utf8_put(char *out, size_t n, size_t out_size,
                               unsigned int cp)
{
  if (cp < 0x80)
    {
      if (n + 1 < out_size)
        {
          out[n++] = (char)cp;
        }
    }
  else if (cp < 0x800)
    {
      if (n + 2 < out_size)
        {
          out[n++] = (char)(0xC0 | (cp >> 6));
          out[n++] = (char)(0x80 | (cp & 0x3F));
        }
    }
  else if (cp < 0x10000)
    {
      if (n + 3 < out_size)
        {
          out[n++] = (char)(0xE0 | (cp >> 12));
          out[n++] = (char)(0x80 | ((cp >> 6) & 0x3F));
          out[n++] = (char)(0x80 | (cp & 0x3F));
        }
    }
  else
    {
      if (n + 4 < out_size)
        {
          out[n++] = (char)(0xF0 | (cp >> 18));
          out[n++] = (char)(0x80 | ((cp >> 12) & 0x3F));
          out[n++] = (char)(0x80 | ((cp >> 6) & 0x3F));
          out[n++] = (char)(0x80 | (cp & 0x3F));
        }
    }

  return n;
}

