router = APIRouter(prefix="/admin", tags=["管理台"])

DEFAULT_ADMIN_PASSWORD = "plant-admin"
ADMIN_PASSWORD = os.environ.get("PLANT_ADMIN_PASSWORD", DEFAULT_ADMIN_PASSWORD)
COOKIE_NAME = "plant_admin"
SERVER_START = time.time()
