#define CLOUD_UPLOAD_EVERY_POLL 1

static void sensor_cloud_upload(void)
{
#ifdef CONFIG_PLANT_AI_MODULE
  struct sensor_view_s v;
  char json[256];

  if (!server_bridge_configured())
    {
      return;
    }

  sensor_service_get_view(&v);
  if (!v.valid)
    {
      return;   /* 传感器不在/读取失败：不上报，保持手机 "--" */
    }

  snprintf(json, sizeof(json),
           "{\"moisture\":%.1f,\"temp\":%.1f,\"ec\":%.1f,"
           "\"salt\":%.2f,\"n\":%.1f,\"p\":%.1f,\"k\":%.1f,\"ph\":%.1f,"
           "\"source\":\"board\"}",
           v.moisture, v.temp, v.ec, v.salt, v.nitrogen,
           v.phosphorus, v.potassium, v.ph);

  if (server_bridge_post_json("sensor", json) == 0)
    {
      printf("[SOIL] 上云 OK moisture=%.1f%%\n", v.moisture);
    }
#else
  (void)0;
#endif
}

static void *sensor_task_entry(void *arg)
{
  int poll_cnt = 0;
  (void)arg;

  printf("[SOIL] sensor thread started\n");

  while (g_running)
    {
      /* 周期休眠 g_interval_ms；read_now() 会 sem_post 提前唤醒立即读。
       * 醒来（无论周期到点还是被唤醒）→ 读一次 + 按节奏上报。 */

      struct timespec ts;

      clock_gettime(CLOCK_REALTIME, &ts);
      ts.tv_sec += g_interval_ms / 1000;
      ts.tv_nsec += (g_interval_ms % 1000) * 1000000L;
      if (ts.tv_nsec >= 1000000000L)
        {
          ts.tv_sec++;
          ts.tv_nsec -= 1000000000L;
        }

      while (sem_timedwait(&g_wake, &ts) != 0)
        {
          if (errno != EINTR)
            {
              break;   /* ETIMEDOUT：周期到点 */
            }
        }

      sensor_poll_once();

      poll_cnt++;

      if ((poll_cnt % CLOUD_UPLOAD_EVERY_POLL) == 0)
        {
          sensor_cloud_upload();
        }
    }

  sem_destroy(&g_wake);
  return NULL;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int sensor_service_start(int interval_ms,
                         void (*on_update)(void *user_data),
                         void *user_data)
{
  int ret;

  if (g_running)
    {
      return 0;
    }

  if (interval_ms <= 0)
    {
      interval_ms = 3000;
    }

  g_interval_ms = interval_ms;
  g_on_update = on_update;
  g_user_data = user_data;
  sem_init(&g_wake, 0, 0);
  g_running = true;

  {
    pthread_attr_t attr;

    pthread_attr_init(&attr);
    pthread_attr_setstacksize(&attr, 8192);   /* 含 E2 HTTP 上报栈 */
    ret = pthread_create(&g_task, &attr, sensor_task_entry, NULL);
    pthread_attr_destroy(&attr);
  }
  if (ret != 0)
    {
      g_running = false;
      return -ret;
    }

  return 0;
}

void sensor_service_stop(void)
{
  if (g_running)
    {
      g_running = false;
      pthread_join(g_task, NULL);
    }
}

void sensor_service_get_view(struct sensor_view_s *out)
{
  if (out == NULL)
    {
      return;
    }

  pthread_mutex_lock(&g_lock);
  *out = g_view;
  pthread_mutex_unlock(&g_lock);
}

void sensor_service_get_history(struct sensor_history_s *out)
{
  if (out == NULL)
    {
      return;
    }

  pthread_mutex_lock(&g_lock);
  *out = g_history;
  pthread_mutex_unlock(&g_lock);
}

int sensor_service_read_now(void)
{
  /* 非阻塞：唤醒轮询线程立即读+上报（不占 UI 线程做串口/HTTP） */
  if (g_running)
    {
      sem_post(&g_wake);
      return 0;
    }

  return -1;
}

