/****************************************************************************
 * Name: soil_sensor_probe
 *
 * Description:
 *   调试用：按指定 从站地址+波特率 发一帧 Modbus 03 查询，返回收到的字节数
 *   （-1 = 一个字节都没收到）。复位/接线排查用（plant soil scan）。
 ****************************************************************************/

int soil_sensor_probe(int addr, int baudrate, uint8_t *resp, int resp_size)
{
  uint8_t cmd[8];
  uint16_t crc;
  int fd;
  int ret;
  int total = 0;
  fd_set rfds;
  struct timeval tv;

  if (resp == NULL || resp_size <= 0)
    {
      return -1;
    }

  fd = open(g_dev, O_RDWR | O_NOCTTY);
  if (fd < 0)
    {
      printf("[SOIL] probe open %s failed: %d\n", g_dev, errno);
      return -1;
    }

  if (soil_sensor_configure_uart(fd, baudrate) < 0)
    {
      close(fd);
      return -1;
    }

  tcflush(fd, TCIFLUSH);

  cmd[0] = (uint8_t)addr;
  cmd[1] = 0x03;
  cmd[2] = 0;
  cmd[3] = 0;
  cmd[4] = 0;
  cmd[5] = 8;
  crc = soil_sensor_crc16(cmd, 6);
  cmd[6] = crc & 0xFF;
  cmd[7] = (crc >> 8) & 0xFF;

  if (write(fd, cmd, 8) != 8)
    {
      close(fd);
      return -1;
    }

  tcdrain(fd);

  tv.tv_sec = 0;
  tv.tv_usec = 250000;
  FD_ZERO(&rfds);
  FD_SET(fd, &rfds);
  ret = select(fd + 1, &rfds, NULL, NULL, &tv);
  if (ret > 0)
    {
      total = read(fd, resp, resp_size);
      if (total < 0) total = 0;
    }

  close(fd);
  return total > 0 ? total : -1;
}
