      lv_obj_set_style_text_color(s_light.value,
                                  lv_color_hex(status_color(view->light_status)), 0);
    }

  if (s_light.note != NULL)
    {
      lv_label_set_text(s_light.note, view->light_status <= 0 ? "有点暗" :
                        (view->light_status == 1 ? "刚刚好" : "很充足"));
    }

  if (s_ec.value != NULL)
    {
      snprintf(buf, sizeof(buf), "%.1f", (double)view->ec);
      lv_label_set_text(s_ec.value, buf);
      lv_obj_set_style_text_color(s_ec.value,
                                  lv_color_hex(status_color(view->ec_status)), 0);
    }

  if (s_ec.note != NULL)
    {
      lv_label_set_text(s_ec.note, view->ec_note[0] != '\0' ?
                        view->ec_note : "--");
    }

  if (hist != NULL)
    {
      for (i = 0; i < SENSOR_HISTORY_DAYS; i++)
        {
          int h;

          if (s_bars[i] == NULL)
            {
              continue;
            }

          if (!hist->valid[i])
            {
              lv_obj_set_height(s_bars[i], 4);
              lv_obj_set_style_bg_color(s_bars[i], lv_color_hex(0xe5e7eb), 0);
              continue;
            }

          h = (int)(hist->moisture[i] * 0.3f);
          if (h < 4)
            {
              h = 4;
            }
          else if (h > 30)
            {
              h = 30;
            }

          lv_obj_set_height(s_bars[i], h);
          lv_obj_set_style_bg_color(s_bars[i],
                                    lv_color_hex((i == SENSOR_HISTORY_DAYS - 1) ?
                                                 0x22c55e : 0x60a5fa), 0);
        }
    }
