  char    ec_note[SENSOR_VIEW_NOTE_LEN];        /* 营养够/缺营养… */
  bool    valid;                   /* 最近一次读取是否成功 */
  uint32_t last_read_ms;           /* 最近一次成功读取时间戳 */
};

