/** 获取最新视图（线程安全：内部加锁拷贝） */
void sensor_service_get_view(struct sensor_view_s *out);

/** 获取7天历史（线程安全） */
void sensor_service_get_history(struct sensor_history_s *out);

/** 立即触发一次读取（UI 下拉刷新用） */
int sensor_service_read_now(void);

