};

static lv_obj_t *s_val[DATA_CARD_NUM];   /* 大数值 label */
static lv_obj_t *s_dot[DATA_CARD_NUM];   /* 状态圆点 */

/* 中性灰：无阈值规则参数（盐分/N/P/K/pH）的圆点颜色 */
#define CLR_DOT_NEUTRAL   0x94a3b8

/****************************************************************************
