static lv_color_t status_color(int status)
{
  switch (status)
    {
      case SENSOR_STATUS_BAD:
        return lv_color_hex(TP_CLR_STATE_BAD);

      case SENSOR_STATUS_WARN:
        return lv_color_hex(TP_CLR_STATE_WARN);

      default:
        return lv_color_hex(TP_CLR_STATE_OK);
    }
}

/* 数据卡：名称(上) + 大数值含单位(下)，右侧状态圆点 */

static lv_obj_t *data_card_create(lv_obj_t *parent, const char *name,
                                  int idx)
{
  lv_obj_t *card = lv_obj_create(parent);
  lv_obj_t *name_l;
  lv_obj_t *val;
  lv_obj_t *dot;

  lv_obj_remove_style_all(card);
  lv_obj_add_style(card, &theme_style_card_small, 0);
  lv_obj_set_style_pad_all(card, 0, 0);

  name_l = lv_label_create(card);
  lv_label_set_text(name_l, name);
  lv_obj_add_style(name_l, &theme_style_text_sub, 0);
  lv_obj_set_pos(name_l, 12, 4);

  val = lv_label_create(card);
  lv_label_set_text(val, "--");
  lv_obj_set_style_text_font(val, TP_FONT_TITLE, 0);
  lv_obj_set_style_text_color(val, lv_color_hex(TP_CLR_TEXT_MAIN), 0);
  lv_obj_set_pos(val, 12, 20);

  dot = lv_obj_create(card);
  lv_obj_remove_style_all(dot);
  lv_obj_set_size(dot, 10, 10);
  lv_obj_set_style_radius(dot, LV_RADIUS_CIRCLE, 0);
  lv_obj_set_style_bg_color(dot, lv_color_hex(CLR_DOT_NEUTRAL), 0);
  lv_obj_set_style_bg_opa(dot, LV_OPA_COVER, 0);
  lv_obj_align(dot, LV_ALIGN_TOP_RIGHT, -12, 16);

  s_val[idx] = val;
  s_dot[idx] = dot;

  return card;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

lv_obj_t *screen_data_create(plant_nav_cb_t cb, void *user_data)
{
  lv_obj_t *scr = lv_obj_create(lv_screen_active());
  lv_obj_t *content;
  lv_obj_t *grid;
  static const char *names[DATA_CARD_NUM] =
  {
    "温度", "水分", "EC", "盐分",
    "氮", "磷", "钾", "pH"
  };

  lv_obj_remove_style_all(scr);
  lv_obj_set_size(scr, 480, 320);

  /* 背景渐变（数据蓝主题） */

  lv_obj_set_style_bg_color(scr, lv_color_hex(0xeff6ff), 0);
  lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);
  lv_obj_set_style_bg_grad_color(scr, lv_color_hex(TP_CLR_BG_GRAD_A), 0);
  lv_obj_set_style_bg_grad_dir(scr, LV_GRAD_DIR_VER, 0);

  widget_topbar_create(scr);

  /* 内容区（一页展示，去滚动，2026-09-09 定案） */

  content = lv_obj_create(scr);
  lv_obj_remove_style_all(content);
  lv_obj_set_pos(content, 0, TP_TOP_BAR_H);
  lv_obj_set_size(content, 480, 320 - TP_TOP_BAR_H - TP_NAV_BAR_H);
  lv_obj_set_style_pad_all(content, TP_PAD_PAGE, 0);
  lv_obj_set_scroll_dir(content, LV_DIR_NONE);

  /* 2×4 数据卡（8 个真实参数） */

  grid = lv_obj_create(content);
  lv_obj_remove_style_all(grid);
  lv_obj_set_size(grid, 448, 181);
  lv_obj_set_pos(grid, 0, 0);
  lv_obj_set_style_pad_row(grid, 3, 0);
  lv_obj_set_style_pad_column(grid, 8, 0);
  lv_obj_set_layout(grid, LV_LAYOUT_GRID);

  static const int32_t col_dsc[] = { 220, 220, LV_GRID_TEMPLATE_LAST };
  static const int32_t row_dsc[] = { 43, 43, 43, 43,
                                     LV_GRID_TEMPLATE_LAST };

  lv_obj_set_grid_dsc_array(grid, col_dsc, row_dsc);

  {
    /* 位置 (col,row)：2 列 × 4 行，行优先 */
    static const int cell[][2] =
    {
      { 0, 0 }, { 1, 0 },
      { 0, 1 }, { 1, 1 },
      { 0, 2 }, { 1, 2 },
      { 0, 3 }, { 1, 3 }
    };
    int i;

    for (i = 0; i < DATA_CARD_NUM; i++)
      {
        lv_obj_t *c = data_card_create(grid, names[i], i);

        lv_obj_set_grid_cell(c, LV_GRID_ALIGN_STRETCH, cell[i][0], 1,
                             LV_GRID_ALIGN_STRETCH, cell[i][1], 1);
      }
  }

  /* 底部导航：本页是"数据"Tab —— 必须显式激活自己，否则默认高亮首页、
   * 且点"首页"因 active==HOME 不触发回调（回不到首页，见 CLAUDE_SYSTEM.md） */

  {
    lv_obj_t *nav = widget_bottomnav_create(scr, cb, user_data);

    widget_bottomnav_set_active(nav, PLANT_TAB_DATA);
  }

  return scr;
}

/* 刷新：把 sensor_service 缓存的 8 个真实参数上屏 */

void screen_data_refresh(const struct sensor_view_s *view,
                         const struct sensor_history_s *hist)
{
  char buf[32];
  int i;

  (void)hist;

  if (view == NULL)
    {
      return;
    }

  if (!view->valid)
    {
      /* 无有效读数：全部 "--"，圆点中性灰（手机/页面不编假数据） */

      for (i = 0; i < DATA_CARD_NUM; i++)
        {
          if (s_val[i] != NULL)
            {
              lv_label_set_text(s_val[i], "--");
            }

          if (s_dot[i] != NULL)
            {
              lv_obj_set_style_bg_color(s_dot[i],
                                        lv_color_hex(CLR_DOT_NEUTRAL), 0);
            }
        }

      return;
    }

  /* 温度（°C） */

  snprintf(buf, sizeof(buf), "%.1f°C", view->temp);
  lv_label_set_text(s_val[DATA_IDX_TEMP], buf);
  lv_obj_set_style_bg_color(s_dot[DATA_IDX_TEMP],
                            status_color(view->temp_status), 0);

  /* 水分（%） */

  snprintf(buf, sizeof(buf), "%.1f%%", view->moisture);
  lv_label_set_text(s_val[DATA_IDX_MOISTURE], buf);
  lv_obj_set_style_bg_color(s_dot[DATA_IDX_MOISTURE],
                            status_color(view->moisture_status), 0);

  /* EC（μS/cm） */

  snprintf(buf, sizeof(buf), "%.0f uS/cm", view->ec);
  lv_label_set_text(s_val[DATA_IDX_EC], buf);
  lv_obj_set_style_bg_color(s_dot[DATA_IDX_EC],
                            status_color(view->ec_status), 0);

  /* 盐分（原始读数） */

  snprintf(buf, sizeof(buf), "%.0f", view->salt);
  lv_label_set_text(s_val[DATA_IDX_SALT], buf);

  /* 氮 / 磷 / 钾（mg/kg） */

  snprintf(buf, sizeof(buf), "%.0f mg/kg", view->nitrogen);
  lv_label_set_text(s_val[DATA_IDX_NITROGEN], buf);

  snprintf(buf, sizeof(buf), "%.0f mg/kg", view->phosphorus);
  lv_label_set_text(s_val[DATA_IDX_PHOSPHORUS], buf);

  snprintf(buf, sizeof(buf), "%.0f mg/kg", view->potassium);
  lv_label_set_text(s_val[DATA_IDX_POTASSIUM], buf);

  /* pH */

  snprintf(buf, sizeof(buf), "%.1f", view->ph);
  lv_label_set_text(s_val[DATA_IDX_PH], buf);
}

