          printf("[SOIL] 摄像头占用中，土壤已挂起\n");
        }

      pthread_mutex_unlock(&g_uart_lock);
      return -1;
    }

  /* 本任务组自己打开串口（不缓存 fd，见文件头说明） */

  fd = open(g_dev, O_RDWR | O_NOCTTY);
  if (fd < 0)
    {
      if (verbose)
