        }

      pthread_mutex_unlock(&g_uart_lock);
      return -1;
    }

  if (soil_sensor_configure_uart(fd, g_baudrate) < 0)
    {
      close(fd);
      pthread_mutex_unlock(&g_uart_lock);
      return -1;
    }

  /* 丢弃上一轮残留脏字节 */

  tcflush(fd, TCIFLUSH);

  if (verbose)
