  char  summary[288];       /* 一句话总结 */
};

/* 协议 v2 图像诊断（两步：media/image → ai/diagnose），结构化返回。 */

int server_bridge_image_diagnose(const uint8_t *frame, size_t frame_len,
                                 struct sb_diag_result_s *out);

