int wifi_manager_connect(const char *ssid, const char *password)
{
  char *argv[8];
  pid_t pid;
  int ret;
  int status;

  if (!g_initialized)
    {
      return -ENODEV;
    }

  if (!ssid || !password)
    {
      return -EINVAL;
    }

  /* Save SSID and password */

  strncpy(g_ssid, ssid, sizeof(g_ssid) - 1);
  strncpy(g_password, password, sizeof(g_password) - 1);

  printf("[WIFI] Connecting to: %s\n", ssid);

  /* Set WiFi password
   * ⚠️ 2026-08-31 修复：wapi psk 第 4 参 = WPA 版本（wapi_str2ndx 数字=下标）：
   *   0=WPA_VER_NONE 1=WPA_VER_1 2=WPA_VER_2 3=WPA_VER_3
   *   原传 "3"（WPA3）→ 家用路由器多为 WPA2 → 版本不匹配 → psk/关联失败
   *   → DHCP 无响应 → 无 IP。改为 "2"（WPA2，最通用）。 */

  argv[0] = "wapi";
  argv[1] = "psk";
  argv[2] = "wlan0";
  argv[3] = (char *)password;
  argv[4] = "2";
  argv[5] = NULL;
  ret = posix_spawn(&pid, "wapi", NULL, NULL, argv, NULL);
  if (ret == 0)
    {
      waitpid(pid, &status, 0);
    }
  else
    {
      printf("[WIFI] Failed to set password: %d\n", ret);
      return ret;
    }

  /* Set WiFi SSID */

  argv[0] = "wapi";
  argv[1] = "essid";
  argv[2] = "wlan0";
  argv[3] = (char *)ssid;
  argv[4] = "1";
  argv[5] = NULL;
  ret = posix_spawn(&pid, "wapi", NULL, NULL, argv, NULL);
  if (ret == 0)
    {
      waitpid(pid, &status, 0);
    }
  else
    {
      printf("[WIFI] Failed to set SSID: %d\n", ret);
      return ret;
    }

  /* Reconnect */

  argv[0] = "wapi";
  argv[1] = "reconnect";
  argv[2] = "wlan0";
  argv[3] = NULL;
  ret = posix_spawn(&pid, "wapi", NULL, NULL, argv, NULL);
  if (ret == 0)
    {
      waitpid(pid, &status, 0);
    }
  else
    {
      printf("[WIFI] Failed to reconnect: %d\n", ret);
      return ret;
    }

  /* Wait for connection */

  sleep(2);

  /* Get IP address — DHCP renew 可能因路由器未完成关联而首次失败，
   * 重试最多 4 次（每次间隔 3s），否则设备无 IP → 后续网络全 ENETUNREACH。 */

  {
    int attempt;

    for (attempt = 0; attempt < 4; attempt++)
      {
        printf("[WIFI] DHCP renew attempt %d/4...\n", attempt + 1);
        argv[0] = "renew";
        argv[1] = "wlan0";
        argv[2] = NULL;
        ret = posix_spawn(&pid, "renew", NULL, NULL, argv, NULL);
        if (ret == 0)
          {
            waitpid(pid, &status, 0);
          }
        else
          {
            printf("[WIFI] Failed to get IP (attempt %d): %d\n",
                   attempt + 1, ret);
          }

        sleep(3);
      }

    /* 打印最终 IP 状态（ifconfig wlan0），确认是否拿到地址 */

    argv[0] = "ifconfig";
    argv[1] = "wlan0";
    argv[2] = NULL;
    ret = posix_spawn(&pid, "ifconfig", NULL, NULL, argv, NULL);
    if (ret == 0)
      {
        waitpid(pid, &status, 0);
      }
  }

  g_connected = true;
  printf("[WIFI] Connected to %s\n", ssid);

  return 0;
}

int wifi_manager_disconnect(void)
{
