 *  不支持的字号返回 NULL。 */
const lv_font_t *zh_font_get(int size_px);

/** 当前策略下 size_px 字体可覆盖字形数（SD 兜底就绪 ≈6763；否则 ≈250） */
int zh_font_count(int size_px);

