/* 复制一个值并去掉行尾 CR/LF（值可能带空格，不做 trim） */

static void cfg_copy_val(const char *val, char *dst, size_t dst_size)
{
  size_t len;

  if (dst == NULL || dst_size == 0)
    {
      return;
    }

  dst[0] = '\0';
  if (val == NULL)
    {
      return;
    }

  len = strnlen(val, dst_size);
  while (len > 0 && (val[len - 1] == '\r' || val[len - 1] == '\n'))
    {
      len--;
    }

  if (len >= dst_size)
    {
      len = dst_size - 1;
    }

  memcpy(dst, val, len);
  dst[len] = '\0';
}

