static const char *wifi_sig_word(int rssi)
{
  if (rssi >= -60)
    {
      return "强";
    }

  if (rssi >= -75)
    {
      return "中";
    }

  return "弱";
}

static uint32_t wifi_sig_color(int rssi)
{
  if (rssi >= -60)
    {
      return TP_CLR_STATE_OK;
    }

  if (rssi >= -75)
    {
      return TP_CLR_STATE_WARN;
    }

