/****************************************************************************
 * Public Functions — 扫描
 ****************************************************************************/

/* 解析 `wapi scan wlan0` 的输出（制表符分隔）：
 *   bssid / frequency / signal level / encode / ssid
 *   08:9b:4b:18:75:e7\t2462\t-86\t0800\tGLHQ2.4G
 * SSID 里可以有空格（取第 5 列到行尾）。同 SSID 只留信号最强的一条，
 * 按信号从强到弱排序。返回条数；打不开输出文件返回负 errno。 */

static int wifi_parse_scan(const char *path, wifi_ap_t *aps, int max)
{
  FILE *fp;
  char line[192];
  int n = 0;
  int i;

  fp = fopen(path, "r");
  if (fp == NULL)
    {
      return -errno;
    }

  while (fgets(line, sizeof(line), fp) != NULL && n < max)
    {
      char *f[4];
      char *p = line;
      char *ssid;
      int k;
      int rssi;

      for (k = 0; k < 4; k++)
        {
          char *tab = strchr(p, '\t');

          if (tab == NULL)
            {
              break;
            }

          *tab = '\0';
          f[k] = p;
          p = tab + 1;
        }

      if (k < 4)
        {
          continue;   /* 表头/短行 */
        }

      if (strlen(f[0]) != 17)
        {
          continue;   /* 不是 bssid 行 */
        }

      ssid = p;

      /* 去行尾 CR/LF */

      {
        size_t l = strlen(ssid);

        while (l > 0 && (ssid[l - 1] == '\r' || ssid[l - 1] == '\n'))
          {
            ssid[--l] = '\0';
          }
      }

      if (ssid[0] == '\0')
        {
          continue;   /* 隐藏 SSID */
        }

      if (strlen(ssid) > 32)
        {
          ssid[32] = '\0';
        }

      rssi = atoi(f[2]);
      if (rssi == 0)
        {
          continue;
        }

      /* 同一个 SSID（路由器多频/多 BSSID）只留信号最强的一条 */

      for (i = 0; i < n; i++)
        {
          if (strcmp(aps[i].ssid, ssid) == 0)
            {
              break;
            }
        }

      if (i < n)
        {
          if (rssi > aps[i].rssi)
            {
              aps[i].rssi = rssi;
            }

          continue;
        }

      strncpy(aps[n].ssid, ssid, sizeof(aps[n].ssid) - 1);
      aps[n].ssid[sizeof(aps[n].ssid) - 1] = '\0';
      aps[n].rssi = rssi;
      aps[n].secure = (strtoul(f[3], NULL, 16) != 0);
      n++;
    }

  fclose(fp);

  /* 简单插入排序：信号强的排前面 */

  for (i = 1; i < n; i++)
    {
      wifi_ap_t tmp = aps[i];
      int j = i - 1;

      while (j >= 0 && aps[j].rssi < tmp.rssi)
        {
          aps[j + 1] = aps[j];
          j--;
        }

      aps[j + 1] = tmp;
    }

  printf("[WIFI] 扫描到 %d 个网络\n", n);
  return n;
}

int wifi_manager_scan(wifi_ap_t *aps, int max)
{
  posix_spawn_file_actions_t fa;
  char *argv[4];
  pid_t pid;
  int ret;
  int status;

  if (aps == NULL || max <= 0)
    {
      return -EINVAL;
    }

  if (!g_initialized)
    {
      return -ENODEV;
    }

  posix_spawn_file_actions_init(&fa);

  /* 把 wapi 的输出重定向到 SD 上的临时文件（父任务读回解析） */

  posix_spawn_file_actions_addopen(&fa, 1, WIFI_SCAN_OUT,
                                   O_WRONLY | O_CREAT | O_TRUNC, 0644);

  argv[0] = "wapi";
  argv[1] = "scan";
  argv[2] = "wlan0";
  argv[3] = NULL;

  ret = posix_spawn(&pid, "wapi", &fa, NULL, argv, NULL);
  posix_spawn_file_actions_destroy(&fa);

  if (ret != 0)
    {
      printf("[WIFI] 扫描启动失败: %d\n", ret);
      return -ret;
    }

  waitpid(pid, &status, 0);
  return wifi_parse_scan(WIFI_SCAN_OUT, aps, max);
}
