static void wkb_apply_layout(void)
{
  static const char *const shift_txt[3] =
  {
    LV_SYMBOL_UP, LV_SYMBOL_DOWN, "abc"
  };
  int r;
  int c;

  for (r = 0; r < WKB_ROWS; r++)
    {
      const char *chars;
      uint8_t n = s_kb_rowlen[s_kb_layout][r];

      if (r == 0)
        {
          chars = s_kb_row0[s_kb_layout];
        }
      else if (r == 1)
        {
          chars = s_kb_row1[s_kb_layout];
        }
      else if (r == 2)
        {
          chars = s_kb_row2[s_kb_layout];
        }
      else
        {
          chars = "zxcvbnm.-_";
        }

      for (c = 0; c < (int)n; c++)
        {
          wkb_key_t *k = &s_kb_keys[r][c];

          if (k->btn == NULL)
            {
              continue;
            }

          if (r == 3 && c == 0)
            {
              k->kind = WKB_TOGGLE;
              k->ch = 0;
              lv_label_set_text(k->lbl, shift_txt[s_kb_layout]);
              if (s_kb_layout == WKB_UPPER)
                {
                  lv_obj_set_style_bg_color(k->btn, lv_color_hex(TP_CLR_GREEN), 0);
                  lv_obj_set_style_text_color(k->lbl, lv_color_hex(0xffffff), 0);
                }
              else
                {
                  lv_obj_set_style_bg_color(k->btn, lv_color_hex(0xdfe7ee), 0);
                  lv_obj_set_style_text_color(k->lbl, lv_color_hex(TP_CLR_TEXT_MAIN), 0);
                }
            }
          else if (r == 2 && c == (int)n - 1)
            {
              k->kind = WKB_BACK;
              k->ch = 0;
              lv_label_set_text(k->lbl, LV_SYMBOL_BACKSPACE);
            }
          else
            {
              k->kind = WKB_CHAR;
              k->ch = chars[c];
              k->txt[0] = chars[c];
              k->txt[1] = '\0';
              lv_label_set_text(k->lbl, k->txt);
            }
        }
    }
}
