    window.addEventListener('online', function(){ dev.net = netLabel(); paintStatus(); });
    window.addEventListener('offline', function(){ dev.net = netLabel(); paintStatus(); });
    var c = navigator.connection;
    if (c && c.addEventListener) c.addEventListener('change', function(){ dev.net = netLabel(); paintStatus(); });
    if (navigator.getBattery) navigator.getBattery().then(function (b) {
      function upd(){ dev.batt = Math.round(b.level*100); paintStatus(); }
      upd();
      b.addEventListener('levelchange', upd);
      b.addEventListener('chargingchange', upd);
    }).catch(function(){});
