  function statusLine() {
    var d = new Date();
    var wk = '日一二三四五六'[d.getDay()];
    var s = pad2(d.getMonth()+1) + '-' + pad2(d.getDate()) + ' 周' + wk + ' ' + pad2(d.getHours()) + ':' + pad2(d.getMinutes());
    if (dev.batt != null) s += ' · 🔋' + dev.batt + '%';
    if (dev.net) s += ' · 📶' + dev.net;
    return s;
  }
  function paintStatus() { var e = $('#status-line'); if (e) e.textContent = statusLine(); }
