      if (opt.type) headers['Content-Type'] = opt.type;
    }
    return fetch(API + path, { method: opt.method || 'GET', headers: headers, body: body })
      .then(function (res) {
        if (res.status === 401 && opt.auth !== false && !opt.retried) {
          opt.retried = true;
          return login().then(function () { return api(path, opt); });
        }
        if (!res.ok) {
          return res.text().then(function (txt) {
            var msg = 'HTTP ' + res.status;
            try { var j = JSON.parse(txt); if (j && j.detail) msg = j.detail; } catch (e) { }
            throw new Error(msg);
