          + esc(shortDate(dates[dates.length - 1])) + '</text>';
      }
    }
    return '<svg viewBox="0 0 ' + W + ' ' + H + '">'
      + grid + ylab + xlab
      + '<path d="' + dpath + '" fill="none" stroke="' + color
      + '" stroke-width="2.2" stroke-linejoin="round" stroke-linecap="round"/>'
      + dots + '</svg>';
  }

