  }
  // 左叶 / 右叶
  if (inEllipse(x, y, 0.335, 0.425, 0.185, 0.105, -33)) col = LEAF_L;
  if (inEllipse(x, y, 0.665, 0.425, 0.185, 0.105, 33)) col = LEAF_R;
  return col;
}

function render(size, ss) {
  const out = Buffer.alloc(size * size * 4);
  const step = 1 / (size * ss);
  for (let py = 0; py < size; py++) {
    for (let px = 0; px < size; px++) {
      let r = 0, g = 0, b = 0, a = 0;
      for (let sy = 0; sy < ss; sy++) {
        for (let sx = 0; sx < ss; sx++) {
          const x = (px * ss + sx + 0.5) * step;
          const y = (py * ss + sy + 0.5) * step;
          const c = sample(x, y);
          if (c) { r += c[0]; g += c[1]; b += c[2]; a += 255; }
        }
      }
      const n = ss * ss;
      const i = (py * size + px) * 4;
      if (a > 0) {
        const cov = a / (255 * n);
        out[i] = Math.round(r / (a / 255));
        out[i + 1] = Math.round(g / (a / 255));
        out[i + 2] = Math.round(b / (a / 255));
        out[i + 3] = Math.round(cov * 255);
      }
    }
  }
  return out;
}

const dir = process.argv[2];
for (const size of [192, 512]) {
  const px = render(size, 4);
  fs.writeFileSync(dir + '\\icon-' + size + '.png', encodePNG(size, size, px));
  console.log('icon-' + size + '.png ok');
}
