package com.zhixiaoban.app;

import android.content.ContentProvider;
import android.content.ContentValues;
import android.content.Context;
import android.database.Cursor;
import android.database.MatrixCursor;
import android.net.Uri;
import android.os.ParcelFileDescriptor;
import android.provider.OpenableColumns;
import android.webkit.MimeTypeMap;

import java.io.File;
import java.io.FileNotFoundException;

public class SimpleFileProvider extends ContentProvider {
    public static final String AUTHORITY_SUFFIX = ".files";

    public static File dir(Context c) {
        File d = new File(c.getCacheDir(), "shared");
        if (!d.exists()) d.mkdirs();
        return d;
    }

    public static Uri getUriForFile(Context c, File f) {
        return new Uri.Builder().scheme("content")
                .authority(c.getPackageName() + AUTHORITY_SUFFIX)
                .appendPath(f.getName()).build();
    }

    @Override public boolean onCreate() { return true; }

    @Override public ParcelFileDescriptor openFile(Uri uri, String mode) throws FileNotFoundException {
        String name = uri.getLastPathSegment();
        File f = new File(dir(getContext()), name);
        return ParcelFileDescriptor.open(f, ParcelFileDescriptor.MODE_READ_WRITE | ParcelFileDescriptor.MODE_CREATE);
    }

    @Override public String getType(Uri uri) {
        String n = uri.getLastPathSegment();
        String ext = n != null && n.contains(".") ? n.substring(n.lastIndexOf('.') + 1) : "";
        String t = MimeTypeMap.getSingleton().getMimeTypeFromExtension(ext.toLowerCase());
        return t == null ? "image/jpeg" : t;
    }

    @Override public Cursor query(Uri uri, String[] projection, String sel, String[] selArgs, String sort) {
        String name = uri.getLastPathSegment();
        File f = new File(dir(getContext()), name);
        String[] cols = projection != null ? projection : new String[]{OpenableColumns.DISPLAY_NAME, OpenableColumns.SIZE};
        MatrixCursor c = new MatrixCursor(cols, 1);
        Object[] row = new Object[cols.length];
        for (int i = 0; i < cols.length; i++) {
            if (OpenableColumns.DISPLAY_NAME.equals(cols[i])) row[i] = name;
            else if (OpenableColumns.SIZE.equals(cols[i])) row[i] = f.length();
            else row[i] = null;
        }
        c.addRow(row);
        return c;
    }

    @Override public Uri insert(Uri uri, ContentValues v) { return null; }
    @Override public int delete(Uri uri, String s, String[] a) { return 0; }
    @Override public int update(Uri uri, ContentValues v, String s, String[] a) { return 0; }
}
