            if (OpenableColumns.DISPLAY_NAME.equals(cols[i])) row[i] = uri.getLastPathSegment();
            else if (OpenableColumns.SIZE.equals(cols[i])) row[i] = (f == null ? 0L : f.length());
            else row[i] = null;
        }
        c.addRow(row);
        return c;
