        "category": p["category"], "category_name": CAT_NAME.get(p["category"], "日常"),
        "topic": p.get("topic") or "",
        "created_at": p["created_at"], "ago": _ago(p["created_at"]),
        "like_count": p.get("like_count") or 0,
