try { fs.rmSync(SHOTS, { recursive: true, force: true }); fs.mkdirSync(SHOTS, { recursive: true }); } catch (e) { }

const errors = [];
const netbad = [];
const report = [];
let n = 0;

const ok = (name, extra) => report.push('PASS  ' + name + (extra ? '  | ' + extra : ''));
const bad = (name, extra) => report.push('FAIL  ' + name + (extra ? '  | ' + extra : ''));

(async () => {
  const browser = await chromium.launch({ channel: 'msedge', headless: true });
  const ctx = await browser.newContext({
    viewport: { width: 412, height: 900 }, deviceScaleFactor: 2,
    isMobile: true, hasTouch: true, locale: 'zh-CN',
  });
  const page = await ctx.newPage();

  page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text().slice(0, 200)); });
  page.on('response', r => {
    const u = r.url();
    if (u.indexOf('/api/') >= 0 && r.status() >= 400) netbad.push(r.status() + ' ' + u.replace('http://127.0.0.1:8011', ''));
  });

  const shot = async (tag) => { n++; await page.screenshot({ path: path.join(SHOTS, String(n).padStart(2, '0') + '_' + tag.replace(/[^\w]/g, '') + '.png') }); };
  const view = async () => page.locator('#view').innerText();
  const txt = async () => (await view()).replace(/\n+/g, ' / ').slice(0, 260);
  const has = async (s) => (await view()).indexOf(s) >= 0;
  const wait = (ms) => page.waitForTimeout(ms || 900);

  async function step(name, fn) {
    try { ok(name, await fn()); }
    catch (e) {
      bad(name, e.message.split('\n').slice(0, 3).join(' ~ ').slice(0, 240));
      await shot('FAIL_' + name).catch(() => { });
    }
  }

  // ── 登录 / 注册 ──
  await page.goto(BASE, { waitUntil: 'domcontentloaded' });
  await wait(1600);

  await step('01 未登录自动进登录页', async () => {
    await page.waitForFunction(() => location.hash === '#/login', null, { timeout: 9000 });
    if (!(await has('登录 / 注册'))) throw new Error('登录页没渲染: ' + await txt());
    return 'hash=' + await page.evaluate(() => location.hash);
  });
  await shot('login');

  const phone = '139' + String(Date.now()).slice(-8);
  await step('02 新手机号注册（验证码自动回填）', async () => {
    await page.fill('#lg-phone', phone);
    await page.click('#lg-send');
    await wait(1600);
    const code = await page.inputValue('#lg-code');
    if (!code) throw new Error('验证码没回填, tip=' + (await page.locator('#lg-tip').innerText()));
