    await wait(2200);
    return phone + ' / code=' + code;
  });
  await shot('home_new_user');

  await step('03 新账号有自动昵称 + 状态栏', async () => {
    const t = await view();
    if (t.indexOf('植友') < 0) throw new Error('没有自动昵称: ' + t.replace(/\n+/g, ' / ').slice(0, 150));
    const bar = (t.split('\n').find(l => l.indexOf('·') >= 0 && (l.indexOf('⚡') >= 0 || l.indexOf('📶') >= 0))) || '';
    return '昵称OK / 状态栏=' + bar.trim();
  });

  // ── 社区 ──
  await step('04 底部导航进社区', async () => {
    await page.click('#tabbar >> text=社区');
    await page.waitForFunction(() => location.hash === '#/community', null, { timeout: 9000 });
    await wait(2000);
