    return c + ' 张图, 首张宽 ' + w + 'px';
  });

  for (const t of [['follow', '关注'], ['photo', '晒图'], ['help', '求助'], ['rank', '排行榜']]) {
    await step('06 社区tab[' + t[1] + ']', async () => {
      await page.click('[data-ctab="' + t[0] + '"]');
      await wait(1500);
      const cls = await page.locator('[data-ctab="' + t[0] + '"]').getAttribute('class');
      if (cls.indexOf('on') < 0) throw new Error('tab 没高亮');
      const body = await view();
      if (t[0] === 'rank' && body.indexOf('花花妈妈') < 0) throw new Error('排行榜没数据');
      if (t[0] === 'follow' && body.indexOf('还没关注谁') < 0 && body.indexOf('@') < 0 && body.indexOf('关注') < 0) throw new Error('关注流异常');
      return body.replace(/\n+/g, ' / ').slice(0, 60);
    });
  }
  await shot('community_rank');

  await step('07 社区搜索"多肉"', async () => {
    await page.click('[data-ctab="recommend"]');
    await wait(1200);
    await page.fill('#cm-search', '多肉');
    await page.press('#cm-search', 'Enter');
    await wait(1800);
    const body = await view();
    if (body.indexOf('多肉') < 0) throw new Error('没搜到: ' + body.replace(/\n+/g, ' / ').slice(0, 150));
    return (body.match(/多肉/g) || []).length + ' 处命中';
  });
  await shot('community_search');

  await step('08 点赞（数字要变）', async () => {
    await page.fill('#cm-search', '');
    await page.press('#cm-search', 'Enter');
    await wait(1600);
    const like = page.locator('.pact[data-like]').first();
    const b = (await like.innerText()).trim();
    await like.click();
    await wait(1300);
    const a = (await page.locator('.pact[data-like]').first().innerText()).trim();
    if (a === b) throw new Error('点赞数没变: ' + b);
    return b + ' -> ' + a;
  });

  await step('09 关注 / 取消关注', async () => {
    const pf = page.locator('.pf[data-follow]').first();
    if (await pf.count() === 0) return '当前流没有可关注的人（已全部关注）';
    const b = (await pf.innerText()).trim();
    await pf.click();
    await wait(1400);
    const a = (await page.locator('.pf[data-follow]').first().innerText()).trim();
    if (a === b) throw new Error('关注状态没变: ' + b);
    return b + ' -> ' + a;
  });

  await step('10 打开帖子详情 + 评论', async () => {
    await page.locator('.post .pt').first().click();
    await page.waitForFunction(() => location.hash === '#/post', null, { timeout: 9000 });
    await wait(1800);
    await page.fill('#cm-in', '这盆养得真好，学习一下');
    await page.click('#cm-send');
    await wait(1800);
    if (!(await has('学习一下'))) throw new Error('评论没出现: ' + await txt());
    return '评论成功';
  });
  await shot('post_detail');

  await step('11 发帖', async () => {
    await page.evaluate(() => { location.hash = '#/compose'; });
    await wait(1600);
    await page.fill('#cf-text', '自动测试发帖：今天的土壤水分 18%，该浇水啦');
    const ph = page.locator('[data-photo]');
    const c = await ph.count();
    if (c > 0) { await ph.first().click(); await wait(500); }
    await page.click('#cf-send');
    await wait(2500);
    const h = await page.evaluate(() => location.hash);
    if (h !== '#/community') throw new Error('发布后没回社区, hash=' + h);
    await wait(1200);
    if (!(await has('自动测试发帖'))) throw new Error('列表里没看到新帖');
    return '发布成功（可配图 ' + c + ' 张）';
  });
  await shot('after_publish');

  await step('12 帖子持久化（刷新后还在）', async () => {
    await page.reload({ waitUntil: 'domcontentloaded' });
    await wait(2800);
    if (!(await has('自动测试发帖'))) throw new Error('刷新后新帖不见了');
    return '刷新后仍在';
  });
