  await page.waitForTimeout(4000);
  console.log('hash=', await page.evaluate(() => location.hash));

  const geo = await page.evaluate(() => {
    const tb = document.getElementById('tabbar');
    const cs = getComputedStyle(tb);
    const r = tb.getBoundingClientRect();
    const kids = [...tb.children].map(c => {
      const cr = c.getBoundingClientRect();
      const hit = document.elementFromPoint(cr.x + cr.width / 2, cr.y + cr.height / 2);
      return { txt: c.innerText.replace(/\n/g, ''), html: c.outerHTML.slice(0, 110), rect: [Math.round(cr.x), Math.round(cr.y), Math.round(cr.width), Math.round(cr.height)], hit: hit ? hit.tagName + '.' + hit.className : null };
    });
    return {
      tabbar: { rect: [Math.round(r.x), Math.round(r.y), Math.round(r.width), Math.round(r.height)], pos: cs.position, z: cs.zIndex, disp: cs.display, pointer: cs.pointerEvents },
      innerH: window.innerHeight, innerW: window.innerWidth, scrollY: window.scrollY,
      docH: document.documentElement.scrollHeight,
      kids,
    };
  });
  console.log(JSON.stringify(geo, null, 1));

  for (const sel of ['#tabbar >> text=社区', '#tabbar .tab:nth-child(4)', 'text=社区']) {
    try {
      await page.click(sel, { timeout: 5000 });
      await page.waitForTimeout(1500);
      console.log(sel + ' -> hash=' + await page.evaluate(() => location.hash));
    } catch (e) {
      console.log(sel + ' ERR: ' + e.message.split('\n').slice(0, 6).join(' ~ '));
    }
    await page.evaluate(() => { location.hash = '#/home'; });
    await page.waitForTimeout(800);
  }
  await browser.close();
})().catch(e => { console.log('CRASH', e.stack); process.exit(1); });
