const SHOTS = 'E:/zhixiaoban_prj/_tmp/uiverify/shots_demo';
fs.rmSync(SHOTS, { recursive: true, force: true });
fs.mkdirSync(SHOTS, { recursive: true });
const rep = [];
let n = 0;
const ok = (a, b) => rep.push('PASS  ' + a + (b ? '  | ' + b : ''));
const bad = (a, b) => rep.push('FAIL  ' + a + (b ? '  | ' + b : ''));
(async () => {
  const browser = await chromium.launch({ channel: 'msedge', headless: true });
  const ctx = await browser.newContext({ viewport: { width: 412, height: 900 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
  const page = await ctx.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text().slice(0, 160)); });
  const view = () => page.locator('#view').innerText();
  const shot = async (t) => { n++; await page.screenshot({ path: SHOTS + '/' + String(n).padStart(2, '0') + '_' + t + '.png' }); };
  const wait = (m) => page.waitForTimeout(m || 900);
  async function step(name, fn) {
    try { ok(name, await fn()); } catch (e) { bad(name, e.message.split('\n').slice(0, 2).join(' ~ ').slice(0, 200)); await shot('FAIL_' + name); }
  }

  await page.goto('http://127.0.0.1:8011/mobile/', { waitUntil: 'domcontentloaded' });
  await wait(1800);

  await step('01 一键演示登录', async () => {
    await page.click('#lg-demo');
    await page.waitForFunction(() => location.hash === '#/home', null, { timeout: 15000 });
    await wait(3000);
    return (await view()).replace(/\n+/g, ' / ').slice(0, 70);
  });
  await shot('demo_home');

  await step('02 保险首页有保障中的植物', async () => {
    await page.evaluate(() => { location.hash = '#/insurance'; });
    await wait(2500);
    const b = await view();
    if (b.indexOf('保障中') < 0) throw new Error('没有保障中: ' + b.replace(/\n+/g, ' / ').slice(0, 150));
    if (b.indexOf('没有植物') >= 0) throw new Error('演示账号居然没有植物');
    return b.replace(/\n+/g, ' / ').slice(0, 110);
  });
  await shot('demo_insurance');

  await step('03 一键理赔（证据齐全应自动通过）', async () => {
    await page.click('#go-claim');
    await page.waitForFunction(() => location.hash === '#/claim', null, { timeout: 9000 });
    await wait(2200);
    await page.locator('[data-cl-plant]').first().click();
    await wait(400);
    const reasons = page.locator('[data-cl-reason]');
    const names = await reasons.allTextContents();
    await reasons.first().click();
    await wait(400);
    await page.fill('#cl-desc', '演示：这两天叶子明显发黄发软');
    const t0 = Date.now();
    await page.click('#cl-go');
    await wait(4000);
    const b = await view();
    if (b.indexOf('ZXB') < 0) throw new Error('没有结论: ' + b.replace(/\n+/g, ' / ').slice(0, 220));
    return '耗时 ' + ((Date.now() - t0) / 1000).toFixed(1) + 's · ' + b.replace(/\n+/g, ' / ').slice(0, 190);
  });
  await shot('demo_claim_result');

  await step('04 预审分与自动通过', async () => {
    const b = await view();
    const m = b.match(/(\d+)\s*\n?\s*预审分/);
    const score = m ? Number(m[1]) : null;
    const auto = b.indexOf('自动通过') >= 0 || b.indexOf('免人工') >= 0;
    if (!auto) throw new Error('证据齐全但没自动通过: ' + b.replace(/\n+/g, ' / ').slice(0, 200));
    return '预审分 ' + score + ' · 自动通过';
  });

  await step('05 自动取证明细有内容', async () => {
    const b = await view();
    const need = ['照片', 'AI 体检', '传感器'];
    const miss = need.filter(k => b.indexOf(k) < 0);
    if (miss.length) throw new Error('缺 ' + miss.join('/') + ': ' + b.replace(/\n+/g, ' / ').slice(0, 220));
    return b.replace(/\n+/g, ' / ').slice(0, 150);
  });

  await step('06 接受赔付 → 已补发', async () => {
    const acc = page.locator('#cl-accept');
    if (await acc.count() === 0) throw new Error('没有「接受赔付」按钮: ' + (await view()).replace(/\n+/g, ' / ').slice(0, 200));
    await acc.click();
    await wait(3200);
    const b = await view();
    if (b.indexOf('补发') < 0 && b.indexOf('已受理') < 0 && b.indexOf('shipped') < 0 && b.indexOf('完成') < 0) {
      throw new Error('状态没更新: ' + b.replace(/\n+/g, ' / ').slice(0, 200));
    }
    return b.replace(/\n+/g, ' / ').slice(0, 150);
  });
  await shot('demo_claim_accepted');

  await step('07 记录回到保险首页', async () => {
    await page.evaluate(() => { location.hash = '#/insurance'; });
    await wait(2500);
    const rows = await page.locator('.claim-row[data-claim]').count();
    if (!rows) throw new Error('理赔记录是空的');
    return rows + ' 条记录';
  });
  await shot('demo_insurance_records');

  await step('08 社区：演示账号自己的帖子排在最前', async () => {
    await page.evaluate(() => { location.hash = '#/community'; });
    await wait(2500);
    const b = await view();
    if (b.indexOf('小绿绿') < 0) throw new Error('没看到演示账号的帖子: ' + b.replace(/\n+/g, ' / ').slice(0, 200));
    return '自己的帖子在';
  });
  await shot('demo_community');

  await browser.close();
  console.log('===== 演示账号流程 =====');
  console.log(rep.join('\n'));
  console.log('\n报错: ' + (errors.length ? errors.join('\n') : '（无）'));
  const f = rep.filter(r => r.indexOf('FAIL') === 0).length;
  console.log('\n结果: ' + (rep.length - f) + '/' + rep.length);
})().catch(e => { console.log('CRASH ' + e.stack); process.exit(1); });

