    if (depth > 6 || out.length >= limit) return;
    let ents = [];
    try { ents = fsx.readdirSync(d, { withFileTypes: true }); } catch (e) { return; }
    for (const e of ents) {
      if (out.length >= limit) return;
      if (['node_modules', '.git', '__pycache__', 'media', 'fonts', 'build', '_backup'].includes(e.name)) continue;
      const p = d + '/' + e.name;
      if (e.isDirectory()) walk(p, depth + 1);
      else if (exts.some(x => e.name.endsWith(x))) {
        let t = '';
        try { t = fsx.readFileSync(p, 'utf8'); } catch (err) { return; }
        if (re.test(t)) out.push(p);
      }
    }
  }
  walk(dir, 0);
  return out;
}
