{"code": "function rg2(dir, re, exts, limit = 30) {
  const out = [];
  function walk(d, depth) {
    if (depth > 7 || out.length >= limit) return;
    let ents = [];
    try { ents = fs3.readdirSync(d, { withFileTypes: true }); } catch (e) { return; }
    for (const e of ents) {
      if (out.length >= limit) return;
      if (['node_modules', '.git', '__pycache__', 'build', '_backup', '.depend'].includes(e.name)) continue;
      if (e.name.includes('.o') || e.name.endsWith('.o')) continue;
      const p = d + '/' + e.name;
      if (e.isDirectory()) walk(p, depth + 1);
      else if (exts.some(x => e.name.endsWith(x))) {
        let t = '';
        try { t = fs3.readFileSync(p, 'utf8'); } catch (err) { return; }
        const m = t.match(re);
        if (m) out.push(p + '  ::' + m[0].slice(0, 60));
      }
    }
  }
  walk(dir, 0);
  return out;
}
