{"code": "function tree(d, depth = 0, maxd = 3) {
  const out = [];
  if (depth > maxd) return out;
  let ents = []; try { ents = fs3.readdirSync(d, { withFileTypes: true }); } catch (e) { return out; }
  for (const e of ents) {
    if (['node_modules', '.git', '__pycache__', 'media'].includes(e.name)) continue;
    out.push('  '.repeat(depth) + e.name + (e.isDirectory() ? '/' : '  ' + fs3.statSync(d + '/' + e.name).size));
    if (e.isDirectory()) out.push(...tree(d + '/' + e.name, depth + 1, maxd));
  }
  return out;
}
