  kind TEXT, name TEXT, mode TEXT DEFAULT 'auto', state TEXT DEFAULT 'idle',
  config_json TEXT, last_run_at TEXT, last_run_by TEXT, last_run_reason TEXT,
  created_at TEXT, updated_at TEXT,
