/* 把 src 拷成 JSON 安全串：可打印 ASCII 里排除 " 和 \\，其余（含中文/控制符）
 * 一律换成 '_'。设备侧发出的 job_id / detail 都是自己可控的，这样最省心。 */

static void sb_json_safe(char *dst, size_t cap, const char *src)
{
  size_t n = 0;

  if (dst == NULL || cap == 0)
    {
